$HOME/.claude/settings.json.text:
{
  "theme": "dark",
  "statusLine": {
    "type": "command",
    "command": "~/.claude/statusline.sh"
  },
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "other-start"
          }
        ]
      },
      {
        "hooks": [
          {
            "command": "pacer status --hook claude-code",
            "timeout": 15,
            "type": "command",
            "statusMessage": "Checking subscription budgets"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Read",
        "hooks": [
          {
            "command": "other-read"
          }
        ]
      },
      {
        "matcher": "Agent|Task",
        "hooks": [
          {
            "command": "pacer guard --planner claude-code",
            "timeout": 15,
            "type": "command"
          }
        ]
      }
    ]
  }
}
